'use strict';

// MODULES //

var pascalcase = require( '@stdlib/string/pascalcase' );
var containsString = require( '@stdlib/assert/contains' );
var ELEMENT_TYPES = require( './../element_types.json' );


// FUNCTIONS //

/**
* Returns the TypeScript DataType name for a given output dtype policy.
*
* @private
* @param {string} policy - output dtype policy
* @returns {string} TypeScript DataType name
*
* @example
* var typeName = outputDtypeTypeScript( 'real_and_generic' );
* // returns 'RealAndGenericDataType'
*
* @example
* var typeName = outputDtypeTypeScript( 'floating_point_and_generic' );
* // returns 'FloatingPointAndGenericDataType'
*/
function outputDtypeTypeScript( policy ) {
	return pascalcase( policy ) + 'DataType';
}

/**
* Returns the TypeScript element type for a dtype policy.
*
* @private
* @param {string} dtypes - dtype policy
* @returns {string} element type
*
* @example
* var type = elementType( 'real_floating_point_and_generic' );
* // returns 'number'
*
* @example
* var type = elementType( 'complex_floating_point_and_generic' );
* // returns 'ComplexLike'
*/
function elementType( dtypes ) {
	return ELEMENT_TYPES[ dtypes ] || 'number';
}

/**
* Returns the ComplexLike import statement if needed.
*
* @private
* @param {string} inputDtypes - input dtype policy
* @param {string} outputDtypes - output dtype policy
* @returns {string} import statement or empty string
*
* @example
* var importStr = complexLikeImport( 'real_and_generic', 'complex_floating_point_and_generic' );
* // returns '\nimport { ComplexLike } from \'@stdlib/types/complex\';'
*
* @example
* var importStr = complexLikeImport( 'real_and_generic', 'real_floating_point_and_generic' );
* // returns ''
*/
function complexLikeImport( inputDtypes, outputDtypes ) {
	var outputElementType;
	var inputElementType;

	outputElementType = ELEMENT_TYPES[ outputDtypes ] || 'number';
	inputElementType = ELEMENT_TYPES[ inputDtypes ] || 'number';
	if (
		containsString( inputElementType, 'ComplexLike' ) ||
		containsString( outputElementType, 'ComplexLike' )
	) {
		return '\nimport { ComplexLike } from \'@stdlib/types/complex\';';
	}
	return '';
}


// EXPORTS //

module.exports = {
	'outputDtypeTypeScript': outputDtypeTypeScript,
	'elementType': elementType,
	'complexLikeImport': complexLikeImport
};
